  for (const auto i : index_range(_scaling_factors))
    if (nonlinear_sys.isScalarVariable(_soln_vars[i]))
      _scaling_factors[i] = nonlinear_sys.getScalarVariable(0, _soln_vars[i]).scalingFactor();
    else
      _scaling_factors[i] = nonlinear_sys.getVariable(/*tid*/ 0, _soln_vars[i]).scalingFactor();

  std::fill(_group_resid.begin(), _group_resid.end(), 0.0);
  std::fill(_group_ref_resid.begin(), _group_ref_resid.end(), 0.0);

  // With a variational inequality (VI) solver, the residual at degrees of freedom in the active
  // set (those held at a bound) is not driven to zero: there the bound constraint holds in place
  // of the residual equation. Exclude those entries from the residual norms, matching the norm
  // PETSc uses for its own VI convergence test.
  std::unique_ptr<NumericVector<Number>> inactive_residual;
  SNES snes = nonlinear_sys.getSNES();
  PetscBool is_vi;
  LibmeshPetscCallA(
      _fe_problem.comm().get(),
      PetscObjectTypeCompareAny((PetscObject)snes, &is_vi, SNESVINEWTONRSLS, SNESVINEWTONSSLS, ""));
  if (is_vi)
  {
    Vec x, f;
    IS active_set;
    LibmeshPetscCallA(_fe_problem.comm().get(), SNESGetSolution(snes, &x));
    LibmeshPetscCallA(_fe_problem.comm().get(), SNESGetFunction(snes, &f, nullptr, nullptr));
    LibmeshPetscCallA(_fe_problem.comm().get(), SNESVIGetActiveSetIS(snes, x, f, &active_set));
    inactive_residual = _residual_vector->clone();
    LibmeshPetscCallA(
        _fe_problem.comm().get(),
        VecISSet(cast_ref<PetscVector<Number> &>(*inactive_residual).vec(), active_set, 0));
    LibmeshPetscCallA(_fe_problem.comm().get(), ISDestroy(&active_set));
  }
  const auto & residual = inactive_residual ? *inactive_residual : *_residual_vector;

  for (const auto i : index_range(_soln_vars))
  {
    if (_converge_on_var[i])
    {
      const auto group = _group_index[i];

      // Prepare residual
      auto resid = Utility::pow<2>(s.calculate_norm(residual, _soln_vars[i], _norm_type));
      if (_unscale_the_residual)
      {
        mooseAssert(_scaling_factors[i], "Scaling factor must not be zero");
        resid /= Utility::pow<2>(_scaling_factors[i]);
      }
      _group_resid[group] += resid;

      // Prepare reference residual. If local norm, this is actually the ratio of the residual
      // dividied by the reference at all DOF
      Real ref_resid;
      if (_local_norm)
      {
        mooseAssert(residual.size() == (*_reference_vector).size(),
                    "Sizes of nonlinear RHS and reference vector should be the same.");
        mooseAssert((*_reference_vector).size(), "Reference vector must be provided.");
        auto ref = _reference_vector->clone();
        // Add a tiny number to the reference to prevent a divide by zero.
        ref->add(std::numeric_limits<Number>::min());
        auto div = residual.clone();
        *div /= *ref;
        ref_resid = Utility::pow<2>(s.calculate_norm(*div, _soln_vars[i], _norm_type));
      }
      else
      {
        ref_resid =
            Utility::pow<2>(s.calculate_norm(*_reference_vector, _soln_vars[i], _norm_type));
        if (_unscale_the_residual)
          ref_resid /= Utility::pow<2>(_scaling_factors[i]);
      }
      _group_ref_resid[group] += ref_resid;
    }
  }

  for (const auto i : index_range(_group_resid))
  {
    _group_resid[i] = std::sqrt(_group_resid[i]);
    _group_ref_resid[i] = std::sqrt(_group_ref_resid[i]);
  }
}

void
ReferenceResidualConvergence::nonlinearConvergenceSetup()
{
  // If no refernce_vector is provided, just revert to DefaultNonlinearConvergence behavior
  if (!_reference_vector)
    return;

  updateReferenceResidual();

  std::ostringstream out;
  out << _name << ": " << _norm_type_enum << " Reference Residual check\n";

  if (_group_names.size() > 0)
  {
    // Set residual and references so that they always have a spacing of 8
    out << std::setprecision(2) << std::scientific;
    unsigned int var_space = 0;
    for (const auto i : index_range(_group_names))
      if (_group_names[i].size() > var_space)
        var_space = _group_names[i].size();

    for (const auto i : index_range(_group_names))
    {
      if (_converge_on_group[i])
      {
        // Print residual
        out << "   " << std::setw(var_space + 8) << std::right << _group_names[i] + "-> res: "
            << (_group_resid[i] < _nl_abs_tol ? COLOR_YELLOW : COLOR_DEFAULT) << std::setw(8)
            << _group_resid[i] << COLOR_DEFAULT;

        // Print res/ref ratio
        if (_local_norm)
          out << "  local res/ref: "
              << (_group_resid[i] / _group_ref_resid[i] < _nl_rel_tol ? COLOR_GREEN : COLOR_DEFAULT)
              << std::setw(8) << _group_ref_resid[i] << COLOR_DEFAULT << "\n";
        else
        {
          // Print reference first if not local norm
          out << "  ref: " << std::setw(8) << _group_ref_resid[i] << "  res/ref: ";

          if (!_group_ref_resid[i])
            out << _group_resid[i] << "\n";
          else
            out << (_group_resid[i] / _group_ref_resid[i] < _nl_rel_tol ? COLOR_GREEN
                                                                        : COLOR_DEFAULT)
                << std::setw(8) << _group_resid[i] / _group_ref_resid[i] << COLOR_DEFAULT << "\n";
        }
      }
    }
    _console << out.str() << std::flush;
  }
}

class ReferenceResidualConvergence : public DefaultNonlinearConvergence,
                                     public ReferenceResidualInterface
{
public:
  static InputParameters validParams();

  ReferenceResidualConvergence(const InputParameters & parameters);

  /// Computes the reference residuals for each group
  void updateReferenceResidual();

  virtual void initialSetup() override;

  class ReferenceVectorTagIDKey
  {
    friend class TaggingInterface;
    ReferenceVectorTagIDKey() {}
    ReferenceVectorTagIDKey(const ReferenceVectorTagIDKey &) {}
  };

  /// Returns the tag ID associated with the reference vector tag ID key
  TagID referenceVectorTagID(ReferenceVectorTagIDKey) const { return _reference_vector_tag_id; }

protected:
  virtual NonlinearSystemBase & nonlinearSystem() override;

  virtual void nonlinearConvergenceSetup() override;

  virtual bool checkResidualConvergence(const unsigned int n_iter,
                                        const Real fnorm,
                                        const Real ref_norm,
                                        const Real rel_tol,
                                        const Real abs_tol,
                                        std::ostringstream & oss) override;

  /**
   * Check the convergence by comparing the norm of each variable's residual separately against
   * its reference variable's norm. Only consider the solution converged if all
   * variables are converged individually using either a relative or absolute
   * criterion.
   * @param fnorm Function norm (norm of full residual vector)
   * @param abs_tol Absolute convergence tolerance
   * @param rel_tol Relative convergence tolerance
   * @param initial_residual_before_preset_bcs Initial norm of full residual vector
   *                                           before applying preset bcs
   * @return true if all variables are converged
   */
  bool checkConvergenceIndividVars(const Real fnorm,
                                   const Real abs_tol,
                                   const Real rel_tol,
                                   const Real initial_residual_before_preset_bcs);

  /// Enum holding the normalization type
  const MooseEnum _norm_type_enum;

  ///@{
  /// List of solution variable names whose reference residuals will be stored,
  /// and the residual variable names that will store them.
  std::vector<NonlinearVariableName> _soln_var_names;
  std::vector<AuxVariableName> _ref_resid_var_names;
  ///@}

  ///@{
  /// List of grouped solution variable names whose reference residuals will be stored
  std::vector<NonlinearVariableName> _group_names;
  ///@}

  ///@{
  /// Variable numbers associated with the names in _soln_var_names and _ref_resid_var_names.
  std::vector<unsigned int> _soln_vars;
  std::vector<unsigned int> _ref_resid_vars;
  ///@}

  ///@{
  /// "Acceptable" absolute and relative tolerance multiplier and
  /// acceptable number of iterations.  Used when checking the
  /// convergence of individual variables.
  const Real _accept_mult;
  const unsigned int _accept_iters;
  ///@}

  /// Nonlinear system to which this convergence object applies.
  const unsigned int _nl_sys_num;

  ///@{
  /// Local storage for *discrete L2 residual norms* of the grouped variables.
  std::vector<Real> _group_ref_resid;
  std::vector<Real> _group_resid;
  ///@}

  /// Vector of bools to signify if variable is in a group.
  std::vector<bool> _is_var_grouped;

  /// Group number index for each variable
  std::vector<unsigned int> _group_index;

  /// Local storage for the scaling factors applied to each of the variables to apply to _ref_resid_vars.
  std::vector<Real> _scaling_factors;

  /// The optional vector storing the reference residual values
  const NumericVector<Number> * _residual_vector;

  /// The vector storing the reference residual values
  const NumericVector<Number> * _reference_vector;

  /// Flag for each solution variable or group being in 'converge_on'
  std::vector<bool> _converge_on_var;
  std::vector<bool> _converge_on_group;

  /// Container for convergence treatment when the reference residual is zero
  const enum class ZeroReferenceType { ZERO_TOLERANCE, RELATIVE_TOLERANCE } _zero_ref_type;

  /// Bool to unscale the residual before convergence checks and screen output
  const bool _unscale_the_residual;

  /// Flag to optionally perform normalization of residual by reference residual before or after L2 norm is computed
  bool _local_norm;

  /// Container for normalization type
  libMesh::FEMNormType _norm_type;

  /// The reference vector tag id
  TagID _reference_vector_tag_id;
};

