      paramError("variable_nl_abs_tol",
                 "The absolute tolerance of variable '",
                 var_name,
                 "' must be non-negative.");
    _group_abs_tol[_group_index[std::distance(_soln_var_names.begin(), it)]] = abs_tol;
  }
  for (const auto i : index_range(_soln_var_names))
  {
    const auto & map = getParam<std::map<std::string, Real>>("variable_nl_abs_tol");
    const auto & group_tol = _group_abs_tol[_group_index[i]];
    const auto it = map.find(_soln_var_names[i]);
    if (group_tol && (it == map.end() || it->second != *group_tol))
      paramError("variable_nl_abs_tol",
