input.content:
#!/usr/bin/env python3
"""List the variables that block convergence in failed nonlinear solves of a MOOSE log.

Usage: blockers.py ABS_TOL REL_TOL LOG [LOG ...]

For each solve that ends in "Solve Did NOT Converge", reads the per-variable residuals
at its last iteration and reports the variables that fail both the absolute and the
relative check. Prints, per blocking variable, the count and the range of residuals.
"""
import re
import sys
from collections import defaultdict

ansi = re.compile(r"\x1b\[[0-9;]*m")
var_line = re.compile(r"^\s+(\S+)-> res: (\S+)\s+ref: (\S+)")

abs_tol = float(sys.argv[1])
rel_tol = float(sys.argv[2])
blocked = defaultdict(list)
for path in sys.argv[3:]:
    last = {}
    current = {}
    with open(path, errors="replace") as f:
        for raw in f:
            line = ansi.sub("", raw)
            m = var_line.match(line)
            if m:
                current[m.group(1)] = (float(m.group(2)), float(m.group(3)))
                continue
            if "Nonlinear |R|" in line and current:
                last = current
                current = {}
            elif "Solve Did NOT Converge" in line:
                for v, (res, ref) in last.items():
                    if res >= abs_tol and res >= rel_tol * ref:
                        blocked[v].append(res)

for v in sorted(blocked):
    r = sorted(blocked[v])
    print(f"{v:36s} solves {len(r):5d} res min {r[0]:.2e} median {r[len(r)//2]:.2e} max {r[-1]:.2e}")

